local root="C:/Users/user/orca/workspaces/CocktailCoffeeTea/coffee-brewing/ArtSource/cafe-title-2026-11-18/revisions/v4-bar-end/"
local pc=app.pixelColor
do local im=Image{fromFile=root.."reference/cafe_wall_effect_right_00.png"} for y=0,im.height-1 do for x=0,im.width-1 do local c=im:getPixel(x,y) if pc.rgbaA(c)>0 then local r,g,b=pc.rgbaR(c),pc.rgbaG(c),pc.rgbaB(c) local yy=(54*r+183*g+19*b)/256 local lift=32*(1-yy/255) im:drawPixel(x,y,pc.rgba(math.min(255,math.floor(r+lift*1.1+.5)),math.min(255,math.floor(g+lift*.86+.5)),math.min(255,math.floor(b+lift*.55+.5)),pc.rgbaA(c))) end end end local sp=Sprite(im.width,im.height,ColorMode.RGB) sp:newCel(sp.layers[1],1,im) sp:saveAs(root.."design/tone-proposal/cafe_wall_effect_right_00.aseprite") sp:saveCopyAs(root.."design/tone-proposal/cafe_wall_effect_right_00.png") sp:close() end
